		{
			title = "Значение",
			text = [=[Для паладинов из Отрекшихся Гарек — доказательство того, что {link:holy-light}Свет{/link} не оставил их в смерти. Для стражей смерти он — капитан, создавший их ряды. Его жизнь соединяет последние дни живого королевства с первыми днями мертвого.]=],
		},
		{
			title = "Деяния",
			text = [=[• При жизни он служил в городской страже столицы под началом капитана Ландена, который выбрал его своим преемником.
• В день, когда {link:arthas-menethil}Артас{/link} убил своего отца, он и Ланден вывели уцелевших через стоки под городом.
• Он отомстил барону Ривендеру, предателю, который выдал королевство {link:cult-of-the-damned}Культу Проклятых{/link}, и умер от ран и чумы.
• Став Отрекшимся, он сражался в первые дни {link:undercity}Подгород{/link}а рядом с соратницей Аней, темным следопытом.
• Он дослужился до капитана стражей смерти.
• Он погиб, защищая Подгород от {link:nak}Нак{/link}срамаса.]=],
		},
	},
	chapters = {
		{
			title = "Последние дни королевства Лордерон",
			hint = [=[Узнайте, что Отрекшиеся Подгорода говорят о своем первом капитане.]=],
			text = [=[Гарек был молодым стражником, жаждавшим битвы, а его капитан, Ланден, говорил ему, что защищать людей — бо́льшая слава. В ночь, когда {link:arthas-menethil}Артас{/link} убил короля {link:terenas-menethil}Теренаса Менетила{/link}, они нашли тронный зал полным сектантов. {link:uther-the-lightbringer}Утер Светоносный{/link} послал их спасать кого смогут. Под городом они увидели, что культ давно был готов. Ланден остался позади, чтобы задержать врага, барона Ривендера, и чтобы Гарек мог увести людей в безопасное место. Гарек так и не простил барона. Он выследил его до Стратхольма и убил его там, а сам умер от ран.]=],
		},
		{
			title = "Вторая жизнь",
			hint = [=[Послушайте, что паладины крепости Бандарион говорят о своем основателе.]=],
			text = [=[Гарек очнулся в подземельях {link:undercity}Подгород{/link}а, не помня ничего, кроме своего имени. Аптекарь Гнилесс хотел пустить его тело на части. Его остановила {link:dark-ranger-anya}Аня{/link}, темный следопыт. Гарек присягнул на верность {link:investigator-silva}Сильва{/link}не и вместе с соратницей собирал в руинах мертвых со свободной волей, расчищал туннели и помогал городу расти. Когда {link:scarlet-crusade}Алый орден{/link} прорвался сквозь стены Подгорода, он повел против него стражей смерти. Где-то в те годы {link:holy-light}Свет{/link} снова начал отвечать ему.]=],
		},
		{
			title = "Крепость его имени",
			hint = [=[Узнайте, почему крепость на утесе Северная скала носит его имя.]=],
			text = [=[Когда {link:nak}Нак{/link}срамас пришел к руинам столицы, {link:forsaken}Отрекшиеся{/link} и {link:argent-dawn}Серебряный Рассвет{/link} вместе сражались с ним на поверхности. Гарек не вернулся. В той битве сражались {link:danitha-morr}Данита Морр{/link} и {link:leonid-barthalomew}Леонид Бартоломей{/link}, и оба потеряли там многих друзей. Когда Данита заняла для своего ордена старую крепость на утесе {link:bandarion-keep}Северная скала{/link}, она назвала ее в его честь.]=],
		},
	},
	mentions = {
		{ text = "Праведное дело" },
		{ text = "{link:bandarion-keep}Крепость Бандарион{/link}" },
		{ text = "Правосудие {link:holy-light}Свет{/link}а" },
	},
	bonds = {
		{ id = "dark-ranger-anya", name = "Темный следопыт Аня", note = "его соратница" },
		{ id = "danitha-morr", name = "Данита Морр", note = "назвала крепость в его честь" },
		{ id = "leonid-barthalomew", name = "Леонид Бартоломей", note = "друг" },
		{ id = "sylvanas-windrunner", name = "Сильвана Ветрокрылая", note = "его королева" },
	},
})

Translate("ruRU", "dark-ranger-anya", {
	title = "Темный следопыт Аня",
	subtitle = "Темный следопыт Королевы-банши",
	found = "Где она в эти дни, неизвестно",
	hint = "Узнайте о ней из рассказов о Гареке Бандарионе.",
	allegiance = "Отрекшиеся · прежде Странники Кель'Таласа",
	aliases = { "Аня" },
	sections = {
		{
			title = "Обзор",
			text = [=[Аня — темный следопыт, одна из мертвых эльфиек, которые служат {link:sylvanas-windrunner}Сильване Ветрокрылой{/link}. При жизни она была следопытом {link:quel-thalas}Кель'Таласа{/link} и служила под ее началом. Она погибла, защищая родину от {link:scourge}Плети{/link}, и восстала ее рабыней. Она помнит все, что делала в то время. Когда она вырвалась на свободу, Сильвана дала ей место, которому можно принадлежать, и за это Аня отдала Темной Госпоже свою верность навсегда.]=],
		},
		{
			title = "Значение",
			text = [=[Аня — одна из первых темных следопытов {link:forsaken}Отрекшихся{/link} и одна из тех, кто видел, как {link:undercity}Подгород{/link} поднимался из туннелей. Она была соратницей {link:garek-bandarion}Гарек{/link}а Бандариона в ранних войнах мертвого королевства. Там, где он утратил воспоминания, она сохранила все свои и научила его тому, что для многих Отрекшихся смерть — чистый лист и вторая жизнь. Живым она доверяет очень мало. Когда паладин старой Серебряной Длани проявил милосердие к работнику из Отрекшихся, а его капитан все равно убил того, Аня сказала соратнику, что живые никогда не увидят в нежити людей и что доверять им нельзя.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она пала, защищая {link:quel-thalas}Кель'Талас{/link}, и творила ужасные дела как рабыня Короля-лича.
• Она не дала аптекарю Гнилессу разрезать на части ее будущего соратника, когда тот очнулся.
• Она сказала ему, что его утраченная память — милость, ибо свои преступления она помнит слишком хорошо.
• Вместе с ним она спасала мертвых со свободной волей из руин столицы.
• Она сражалась рядом с ним против Алого ордена и против {link:nak}Нак{/link}срамаса.
• Вместе с двумя другими, {link:investigator-silva}Сильва{/link}ной и темным следопытом Клеей, она ездила в {link:the-marris-stead}Поместье Маррисов{/link} на поиски человека по имени {link:nathanos-blightcaller}Натанос Маррис{/link}.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись этих дней не говорит, где Аня служит теперь и что она делала после того, как пал {link:garek-bandarion}Гарек{/link}.]=],
		},
	},
	bonds = {
		{ id = "garek-bandarion", name = "Гарек Бандарион", note = "ее соратник" },
		{ id = "sylvanas-windrunner", name = "Сильвана Ветрокрылая", note = "ее королева" },
	},
})

Translate("ruRU", "danitha-morr", {
	title = "Данита Морр",
	subtitle = "Командир крепости Бандарион",
	found = "Крепость Бандарион",
	hint = [=[Поговорите с предводительницей паладинов в крепости Бандарион.]=],
	allegiance = "Дозор Тира · Отрекшиеся",
	aliases = { "Данита" },
	sections = {
		{
			title = "Обзор",
			text = [=[Данита Морр ведет паладинов {link:morgan-s-vigil}Дозор{/link}а Тира из крепости Бандарион. Она называет себя тем, что в этой крепости ближе всего к командиру. Она сражалась, защищая {link:undercity}Подгород{/link}, когда пришел {link:nak}Нак{/link}срамас, и потеряла там друзей, и среди них был {link:garek-bandarion}Гарек Бандарион{/link}. Заняв разрушенную крепость на утесе {link:bandarion-keep}Северная скала{/link}, она назвала ее в его честь.]=],
		},
		{
			title = "Значение",
			text = [=[Данита пытается сделать то, чего прежде не делал ни один Отрекшийся: создать среди мертвых орден {link:holy-light}Света{/link} и завоевать ему место в их королевстве. Ее народ боится паладинов. Ее королева им не доверяет. Она полагает, что этот труд может занять десятилетия, и все равно его делает.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она восстанавливает крепость Бандарион из того, что удается добыть в руинах деревни {link:shadowvale}Долина Теней{/link}.
• Она охотится на отступников, называемых Потускневшими, — восставших паладинов, которые обращают клинки против Отрекшихся.
• Она посылает своих паладинов помогать беднякам {link:undercity}Подгород{/link}а.
• Она посылает свой орден в {link:silverpine-forest}Серебряный бор{/link}, чтобы завоевать доверие {link:horde}Орды{/link}.]=],
		},
		{ title = "Чего нет в летописях", text = "О ее жизни до смерти написано мало." },
	},
	chapters = {
		{
			title = "Дом в холмах",
			hint = [=[Найдите дорогу к крепости Бандарион и познакомьтесь с ее командиром.]=],
			text = [=[Когда пришли ее паладины, крепость лежала в руинах. {link:murlocs}Мурлоки{/link} Мерзкого Плавника устроили в ней нерестилище и бились, чтобы вернуть ее, даже после того как их выгнали. У нее было мало материалов, еще меньше союзников и великое множество стен, которые надо было чинить. Данита радушно принимала каждого пришедшего, кто все еще держался {link:holy-light}Свет{/link}а.]=],
		},
		{
			title = "Отступники",
			hint = [=[Разберитесь с восставшими паладинами, которые сделали деревню Долина Теней своим логовом.]=],
			text = [=[Не каждый восставший паладин способен принять то, чем он стал. Некоторые хранят ненависть прежней жизни и убивают Отрекшихся, которых встречают. Каждое такое убийство облегчает врагам ордена задачу сеять страх. Данита велела уничтожить отступников в деревне {link:shadowvale}Долина Теней{/link}, а их командира, Рудольфа {link:rudolph-gelhardt}Гельхардт{/link}а, обезглавить.]=],
		},
		{
			title = "Знак доброй воли",
			hint = "Отнесите дар паладинов Темной Госпоже.",
			text = [=[Данита послала голову отступника в {link:undercity}Подгород{/link}, чтобы показать Темной Госпоже, что {link:tyr-s-watch}Дозор Тира{/link} сам наводит порядок в своем доме. {link:sylvanas-windrunner}Сильвана{/link} не усомнилась в ее искренности. Она сказала, что ждет, что с ума сойдут и другие паладины, и что однажды она может решить больше не терпеть этот орден. Она велела его паладинам служить хорошо и сказала, что будет наблюдать.]=],
		},
	},
	mentions = {
		{ text = "Обход владений" },
		{ text = "Отступники" },
		{ text = "Знак доброй воли" },
		{ text = "Урок божественного" },
		{ text = "Дипломатическое происшествие" },
		{ text = "Праведное дело" },
	},
	bonds = {
		{ id = "garek-bandarion", name = "Гарек Бандарион", note = "павший друг" },
		{ id = "leonid-barthalomew", name = "Леонид Бартоломей", note = "старый боевой товарищ" },
		{ id = "rudolph-gelhardt", name = "Рудольф Гельхардт", note = "командир отступников" },
		{ id = "sylvanas-windrunner", name = "Сильвана Ветрокрылая", note = "не доверяет ее ордену" },
	},
})

